        current = Self::classify_invalid_input(current);
        current = Self::classify_invalid_data(current);
        current = Self::classify_other_error(current);
        current = Self::retain_error_kind(current);
        current = Self::restore_error_kind(current);
        current = Self::fold_error_kind(current);
        current = Self::mask_error_kind(current);
        current = Self::select_error_kind(current);
        current = Self::clamp_error_kind(current);
        current = Self::align_error_kind(current);
        current = Self::quantize_error_kind(current);
        current = Self::settle_error_kind(current);
        current = Self::bound_error_kind(current);
        current = Self::merge_error_kind(current);
        current = Self::scale_error_kind(current);
